    .nav-logo svg { width: 28px; height: 28px; }

    .nav-links {
      display: flex;
      gap: 32px;
      align-items: center;
    }

    .nav-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 14px;
      font-weight: 500;
      transition: color var(--transition);
    }

    .nav-links a:hover { color: var(--primary); }

    .nav-cta {
      background: var(--primary);
      color: var(--white) !important;
      padding: 8px 20px;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }

    .nav-cta:hover { background: #333; }

    /* Announcement Bar */
    .announcement {
      background: var(--primary);
      color: var(--white);
      text-align: center;
      padding: 10px 20px;
      font-size: 13px;
      font-weight: 500;
      margin-top: 64px;
    }

    .announcement span { color: #A5B4FC; }

    /* Hero */
    .hero {
      text-align: center;
      padding: 100px 20px 80px;
      max-width: 800px;
      margin: 0 auto;
    }

    .hero h1 {
      font-size: clamp(36px, 6vw, 56px);
      font-weight: 700;
      line-height: 1.1;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
    }

    .hero p {
      font-size: 18px;
      color: var(--text-secondary);
      margin-bottom: 36px;
      line-height: 1.6;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .btn-primary {
      background: var(--accent);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 15px;
      text-decoration: none;
      transition: background var(--transition), transform var(--transition);
      border: none;
      cursor: pointer;
    }

    .btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); }

    .btn-secondary {
      background: var(--surface);
      color: var(--primary);
      padding: 14px 28px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 15px;
      text-decoration: none;
      transition: background var(--transition), transform var(--transition);
      border: 1px solid var(--border);
