    .trusted-by-logos svg {
      height: 28px;
      width: auto;
    }

    /* Stats */
    .stats {
      padding: 100px 20px;
      text-align: center;
    }

    .stats h2 {
      font-size: 14px;
      color: var(--text-secondary);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 48px;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      max-width: 800px;
      margin: 0 auto;
    }

    .stat-item h3 {
      font-size: clamp(40px, 8vw, 64px);
      font-weight: 700;
      color: var(--primary);
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-item p {
      font-size: 15px;
      color: var(--text-secondary);
    }

    /* Features Search */
    .features-search {
      padding: 80px 20px;
      background: var(--surface);
    }

    .section-header {
      text-align: center;
      max-width: 600px;
      margin: 0 auto 48px;
    }

    .section-header h2 {
      font-size: 32px;
      font-weight: 700;
      margin-bottom: 16px;
    }

    .section-header p {
      color: var(--text-secondary);
      font-size: 16px;
    }

    .search-container {
      max-width: 1100px;
      margin: 0 auto;
    }

    .search-tabs {
      display: flex;
      gap: 8px;
      justify-content: center;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }

    .search-tab {
