      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 100px;
      font-size: 13px;
      font-weight: 500;
      white-space: nowrap;
      cursor: pointer;
      transition: all var(--transition);
      color: var(--text-secondary);
    }

    .filter-pill:hover { border-color: var(--accent); color: var(--accent); }

    .filter-pill.active {
      background: var(--accent);
      color: var(--white);
      border-color: var(--accent);
    }

    .screenshot-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .screenshot-card {
      background: var(--white);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      aspect-ratio: 9/16;
      position: relative;
    }

    .screenshot-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .screenshot-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
      color: var(--text-secondary);
      font-size: 12px;
    }

    /* Features Flows */
    .features-flows {
      padding: 100px 20px;
    }

    .flows-toggle {
      display: flex;
      gap: 0;
      justify-content: center;
      margin-bottom: 48px;
      background: var(--surface);
      border-radius: 100px;
      padding: 4px;
      width: fit-content;
      margin-left: auto;
      margin-right: auto;
    }

    .flows-toggle button {
      padding: 12px 32px;
      border: none;
      background: transparent;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      border-radius: 100px;
      transition: all var(--transition);
      color: var(--text-secondary);
    }

    .flows-toggle button.active {
      background: var(--white);
      color: var(--primary);
      box-shadow: var(--shadow);
    }

    .flows-content {
      max-width: 900px;
      margin: 0 auto;
    }

    .flow-view {
      display: none;
    }

    .flow-view.active { display: block; }

    .flow-video {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--primary);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
    }

    .flow-video-play {
      width: 80px;
      height: 80px;
      background: rgba(255,255,255,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .flow-prototype {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .prototype-step {
      background: var(--surface);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .prototype-step-img {
      aspect-ratio: 9/16;
      background: linear-gradient(135deg, #e8e8e8 0%, #d0d0d0 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      color: var(--text-secondary);
    }

    .prototype-step-num {
      padding: 12px;
      font-size: 13px;
      font-weight: 600;
      text-align: center;
      border-top: 1px solid var(--border);
