    .cta .btn-primary {
      background: var(--white);
      color: var(--primary);
    }

    .cta .btn-primary:hover { background: #f0f0f0; }

    .cta .btn-secondary {
      background: transparent;
      color: var(--white);
      border-color: rgba(255,255,255,0.3);
