    .brand-marquee-row {
      display: flex;
      gap: 60px;
      justify-content: center;
      align-items: center;
      padding: 16px 0;
      opacity: 0.5;
    }

    .brand-marquee-row span {
      font-size: 20px;
      font-weight: 600;
