    .footer-brand h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .footer-brand p {
      font-size: 14px;
      color: var(--text-secondary);
      margin-bottom: 24px;
    }

    .footer-col h4 {
