    @media (max-width: 480px) {
      .screenshot-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
      .flow-prototype { grid-template-columns: 1fr; }
      .search-tabs { gap: 6px; }
      .search-tab { padding: 8px 14px; font-size: 13px; }
    }
  </style>
</head>
